/**
 * Equipment data shared by the OPC UA and EMS contracts (Phase 6 slice 6b-0; DI-49, DI-32, DI-31; plan
 * docs/build-plan/phase-6/slice-6b-0-interfaces.md). Pure: zod and node:crypto only, no kernel import.
 *
 *  - Status quality: the source's status code kept as received (OPC UA StatusCode as 0xXXXXXXXX), read as GOOD,
 *    UNCERTAIN or BAD from its two severity bits.
 *  - Native samples: a value exactly as the source sent it (raw text, for example a Double written 1.25E1) with the
 *    decimal value the eBMR shows; the raw text must state the shown value exactly (DI-32: never rounded).
 *  - Series chunks: consecutive samples of one tag of one equipment or room, with a SHA-256 over a canonical text that
 *    the database recomputes (recipe-core 0960 plant.series_chunk_hash).
 *  - Alarm and equipment-event lifecycles: what a source reports (RAISED, CLEARED, SOURCE_ACKNOWLEDGED; state changes);
 *    the eBMR's own acknowledgment is a person's act in the eBMR, never the source's (DI-49).
 *  - Dynamic data references: how an entry, a review or a report names a stretch of native data.
 *
 * Every number travels as text; nothing here converts a GMP value to a JavaScript number.
 */
import { createHash } from 'node:crypto';
import { z } from 'zod';
import { SourceCode, SourceText, SourceValue } from './contract.ts';
import { EpochMicrosText, Sha256Hex } from './envelope.ts';

// ---------------------------------------------------------------------------------------------------------------
// Status quality
// ---------------------------------------------------------------------------------------------------------------

/** A source status code as received: OPC UA StatusCode written 0x followed by eight upper-case hex digits. */
export const StatusCodeText = z.string().regex(/^0x[0-9A-F]{8}$/, 'a status code such as 0x00000000');
export type StatusCodeText = z.infer<typeof StatusCodeText>;

export const SAMPLE_QUALITIES = ['GOOD', 'UNCERTAIN', 'BAD'] as const;
export const SampleQuality = z.enum(SAMPLE_QUALITIES);
export type SampleQuality = z.infer<typeof SampleQuality>;

/** GOOD, UNCERTAIN or BAD from the two severity bits of a status code (OPC UA Part 4: 00 good, 01 uncertain, 1x bad). */
export function qualityOfStatus(code: StatusCodeText): SampleQuality {
  const top = code.charAt(2);
  if ('0123'.includes(top)) return 'GOOD';
  if ('4567'.includes(top)) return 'UNCERTAIN';
  return 'BAD';
}

// ---------------------------------------------------------------------------------------------------------------
// Raw values and the value shown
// ---------------------------------------------------------------------------------------------------------------

/** A numeric value as the source wrote it: decimal or exponent notation, at most 40 characters. */
export const RawNumberText = z.string().regex(/^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]{1,3})?$/, 'a number as the source wrote it').max(40);
/** The decimal text the eBMR shows (no exponent, no plus sign). */
export const ShownDecimal = z.string().regex(/^-?(0|[1-9][0-9]*)(\.[0-9]+)?$/, 'decimal text such as 12.50');

/**
 * The canonical form of a number written in decimal or exponent notation: sign, digits without leading zeros, a point
 * only when there are fraction digits, no trailing fraction zeros, zero as "0". String arithmetic only (no float).
 * Null when the text is not a number.
 */
export function canonicalDecimal(text: string): string | null {
  const m = /^([+-]?)([0-9]*)(?:\.([0-9]*))?(?:[eE]([+-]?[0-9]{1,3}))?$/.exec(text);
  if (!m || (m[2] === '' && (m[3] ?? '') === '')) return null;
  const sign = m[1] === '-' ? '-' : '';
  let digits = `${m[2] ?? ''}${m[3] ?? ''}`;
  let point = (m[2] ?? '').length + Number.parseInt(m[4] ?? '0', 10);
  // Pad so that the point falls inside the digit string.
  if (point < 0) {
    digits = '0'.repeat(-point) + digits;
    point = 0;
  }
  if (point > digits.length) digits = digits + '0'.repeat(point - digits.length);
  const intPart = digits.slice(0, point).replace(/^0+/, '') || '0';
  const fracPart = digits.slice(point).replace(/0+$/, '');
  const body = fracPart === '' ? intPart : `${intPart}.${fracPart}`;
  return body === '0' ? '0' : `${sign}${body}`;
}

/**
 * Why `shown` is not exactly the value `raw` states (DI-32: the raw output must match the displayed value; a shown
 * value is never a rounding of the raw one), or null when it is.
 */
export function shownValueProblem(raw: string, shown: string): string | null {
  if (!RawNumberText.safeParse(raw).success) return `${raw} is not a number as a source writes it`;
  if (!ShownDecimal.safeParse(shown).success) return `${shown} is not decimal text`;
  if (canonicalDecimal(raw) !== canonicalDecimal(shown)) return `the shown value ${shown} is not the value ${raw} the device sent`;
  return null;
}

// ---------------------------------------------------------------------------------------------------------------
// Native samples and series chunks (plant.series)
// ---------------------------------------------------------------------------------------------------------------

/**
 * One sample in native form: the source's timestamp (and the source server's, when it has one), the raw value as text,
 * the decimal value shown (null when the status is BAD or the value is not a number), and the status code.
 */
export const NativeSample = z.strictObject({
  sourceTime: EpochMicrosText,
  serverTime: EpochMicrosText.nullable(),
  raw: z.string().min(1).max(64),
  value: ShownDecimal.nullable(),
  status: StatusCodeText,
});
export type NativeSample = z.infer<typeof NativeSample>;

/** Whose data a series, an alarm or an event is: a unit of plant.equipment or a room or line of plant.area. */
export const SUBJECT_KINDS = ['EQUIPMENT', 'AREA'] as const;
export const SubjectKind = z.enum(SUBJECT_KINDS);
export type SubjectKind = z.infer<typeof SubjectKind>;

/** A tag name: a released process tag (process/tags.ts) or an EMS room tag (systems/ems.ts). */
export const TagName = z.string().regex(/^[a-z][a-z0-9_]*(\.[a-zA-Z0-9_]+)+$/, 'a tag such as force.main_kN').max(64);

/** The most samples one chunk carries. */
export const SERIES_CHUNK_MAX_SAMPLES = 2000;

export const SeriesChunkV1 = z
  .strictObject({
    subjectKind: SubjectKind,
    subjectCode: SourceCode,
    tag: TagName,
    unit: SourceValue.shape.unit,
    /** The chunk's number in the feed of this subject and tag: 1, 2, 3, ... (a gap is visible). */
    chunkNo: z.string().regex(/^[1-9][0-9]{0,17}$/),
    samples: z.array(NativeSample).min(1).max(SERIES_CHUNK_MAX_SAMPLES),
    chunkHash: Sha256Hex,
  })
  .superRefine((c, ctx) => {
    let prev = -1n;
    c.samples.forEach((s, i) => {
      const t = BigInt(s.sourceTime);
      if (t <= prev) ctx.addIssue({ code: 'custom', path: ['samples', i, 'sourceTime'], message: 'source times increase within a chunk' });
      prev = t;
      if (s.value !== null && qualityOfStatus(s.status) === 'BAD') ctx.addIssue({ code: 'custom', path: ['samples', i, 'value'], message: 'a sample with a BAD status shows no value' });
      if (s.value !== null) {
        const problem = shownValueProblem(s.raw, s.value);
        if (problem) ctx.addIssue({ code: 'custom', path: ['samples', i, 'value'], message: problem });
      }
    });
    if (c.chunkHash !== seriesChunkHash(c)) ctx.addIssue({ code: 'custom', path: ['chunkHash'], message: 'the chunk hash does not match its samples' });
  });
export type SeriesChunkV1 = z.infer<typeof SeriesChunkV1>;

/**
 * The canonical text of a chunk, hashed by the source and recomputed by the database: a header line
 * `subjectKind|subjectCode|tag|unit|chunkNo`, then one line per sample `sourceTime|serverTime|raw|value|status` (an empty
 * field for null), joined with `\n`, UTF-8.
 */
export function seriesChunkText(c: Pick<SeriesChunkV1, 'subjectKind' | 'subjectCode' | 'tag' | 'unit' | 'chunkNo' | 'samples'>): string {
  const head = [c.subjectKind, c.subjectCode, c.tag, c.unit, c.chunkNo].join('|');
  return [head, ...c.samples.map((s) => [s.sourceTime, s.serverTime ?? '', s.raw, s.value ?? '', s.status].join('|'))].join('\n');
}

export function seriesChunkHash(c: Pick<SeriesChunkV1, 'subjectKind' | 'subjectCode' | 'tag' | 'unit' | 'chunkNo' | 'samples'>): string {
  return createHash('sha256').update(seriesChunkText(c), 'utf8').digest('hex');
}

// ---------------------------------------------------------------------------------------------------------------
// Alarms and equipment events (plant.alarm, plant.equipment_state_event)
// ---------------------------------------------------------------------------------------------------------------

/**
 * What a source reports about one alarm occurrence (one raise to its clear). RAISED opens it in the eBMR; CLEARED and
 * SOURCE_ACKNOWLEDGED are later transitions of the same occurrence. The eBMR's acknowledgment with the action taken
 * (and a comment for a GMP-critical alarm) is a person's act in the eBMR (plant.acknowledge_alarm), never the source's.
 */
export const ALARM_TRANSITIONS = ['RAISED', 'CLEARED', 'SOURCE_ACKNOWLEDGED'] as const;
export const AlarmTransition = z.enum(ALARM_TRANSITIONS);
export type AlarmTransition = z.infer<typeof AlarmTransition>;

/** Which limit was crossed (STATE: a discrete condition such as a door open, a feed gap or a reject burst). */
export const LIMIT_KINDS = ['HIGH_HIGH', 'HIGH', 'LOW', 'LOW_LOW', 'DEVIATION', 'RATE', 'STATE'] as const;
export const LimitKind = z.enum(LIMIT_KINDS);
export type LimitKind = z.infer<typeof LimitKind>;

export const AlarmCode = z.string().regex(/^[A-Z][A-Z0-9_.-]{0,63}$/, 'an alarm code such as FORCE_MAIN_HIGH');

export const EquipmentAlarmV1 = z
  .strictObject({
    subjectKind: SubjectKind,
    subjectCode: SourceCode,
    /** The source's id of this occurrence (an OPC UA ConditionId with the raising EventId, an EMS alarm number). */
    occurrenceId: z.string().regex(/^[\x21-\x7E]{1,128}$/),
    transition: AlarmTransition,
    alarmCode: AlarmCode,
    /** The source's severity, 1 (lowest) to 1000 (OPC UA), as text; informative only (the GMP-critical flag is the eBMR's). */
    severity: z.string().regex(/^([1-9][0-9]{0,2}|1000)$/),
    tag: TagName.nullable(),
    value: SourceValue.nullable(),
    limit: SourceValue.nullable(),
    limitKind: LimitKind.nullable(),
    message: SourceText,
    occurredAt: EpochMicrosText,
  })
  .refine((a) => (a.limit === null) === (a.limitKind === null || a.limitKind === 'STATE'), { message: 'a limit is given exactly when a limit other than STATE was crossed', path: ['limit'] });
export type EquipmentAlarmV1 = z.infer<typeof EquipmentAlarmV1>;

export const EQUIPMENT_STATES = ['IDLE', 'RUNNING', 'HELD', 'STOPPED', 'FAULTED', 'MAINTENANCE'] as const;
export const EquipmentState = z.enum(EQUIPMENT_STATES);
export type EquipmentState = z.infer<typeof EquipmentState>;

/**
 * Equipment events a source reports (EU GMP Chapter 4 relevant events in the record): a state change, a recipe loaded
 * (with its version, compared with the MBR's), a recipe mismatch found by the source, a phase start or end, an
 * operator action at the panel, a fault.
 */
export const EQUIPMENT_EVENT_KINDS = ['STATE_CHANGED', 'RECIPE_LOADED', 'RECIPE_MISMATCH', 'PHASE_STARTED', 'PHASE_ENDED', 'OPERATOR_ACTION', 'FAULT'] as const;
export const EquipmentEventKind = z.enum(EQUIPMENT_EVENT_KINDS);
export type EquipmentEventKind = z.infer<typeof EquipmentEventKind>;

export const EquipmentEventV1 = z
  .strictObject({
    equipmentCode: SourceCode,
    /** The source's unique id of the event (an OPC UA EventId as hex). */
    eventId: z.string().regex(/^[\x21-\x7E]{1,128}$/),
    kind: EquipmentEventKind,
    state: EquipmentState.nullable(),
    recipeVersion: z.string().regex(/^[\x21-\x7E]{1,64}$/).nullable(),
    message: SourceText,
    occurredAt: EpochMicrosText,
  })
  .refine((e) => (e.kind === 'STATE_CHANGED') === (e.state !== null), { message: 'a state is given exactly with STATE_CHANGED', path: ['state'] })
  .refine((e) => !['RECIPE_LOADED', 'RECIPE_MISMATCH'].includes(e.kind) || e.recipeVersion !== null, { message: 'a recipe event names the recipe version', path: ['recipeVersion'] });
export type EquipmentEventV1 = z.infer<typeof EquipmentEventV1>;

// ---------------------------------------------------------------------------------------------------------------
// Dynamic data references
// ---------------------------------------------------------------------------------------------------------------

/**
 * A stretch of native data an entry, a review or a report refers to (DI-32: the native data, not a picture of them):
 * one tag of one subject over [from, to) of source time, optionally in a batch and step's context. The viewer reads it
 * back from plant.series (the equipment-data namespace).
 */
export const DynamicDataRef = z
  .strictObject({
    kind: z.literal('SERIES'),
    subjectKind: SubjectKind,
    subjectCode: SourceCode,
    tag: TagName,
    fromUs: EpochMicrosText,
    toUs: EpochMicrosText,
    batchId: z.uuid().nullable(),
    step: z.string().min(1).max(200).nullable(),
  })
  .refine((r) => BigInt(r.fromUs) < BigInt(r.toUs), { message: 'from is before to', path: ['toUs'] });
export type DynamicDataRef = z.infer<typeof DynamicDataRef>;

packages/integration-sdk/src/process/wir.source:
/**
 * Process equipment wire formats between the site gateway and the tablets server (Phase 3 slice 3a, G-06; the 3a
 * interface of docs/build-plan/phase-3/slice-3-plan.md). Same gateway authentication and session as the scale
 * uplink (bearer token of the gateway login, GATEWAY_UPLINK_PREFIX):
 *
 *   POST /gw/v1/process-readings              ProcessReadingsRequest: actual values, setpoint read-backs and alarms
 *   GET  /gw/v1/setpoint-downloads            SetpointDownloadsResponse: setpoints pending for this gateway's devices
 *   POST /gw/v1/setpoint-downloads/:id/ack    SetpointAckRequest: written and read back (or not), with the read-back
 *
 * Every value is decimal text in the tag's unit with at most the tag's fraction digits (never a JavaScript number);
 * `sourceTime` is the gateway's clock when the value was read, UTC epoch microseconds as text (as the scale wire's
 * sourceTimeUs); `sequence` is the gateway's counter per device (1, 2, 3, ... without gaps over the device's life on
 * this gateway, kept across restarts by the gateway's journal), so the server sees a lost, repeated or reordered
 * reading (DI-31). `sessionId` is the gateway's capture session: a UUID the gateway draws at each start, so a reading
 * delivered later from the journal still names the run of the gateway that took it.
 *
 * processReadingsProblems() is the pure validator of a request body: the schema plus the rules a schema cannot say
 * (known tag, the tag's unit, fraction digits, whole non-negative counters, read-backs only of setpoint tags, one
 * sequence number once per device and increasing within a batch).
 */
import { z } from 'zod';
import { DECIMAL_TEXT, scaleOf } from '../scale/decimal.ts';
import { shownValueProblem } from '../adapter/equipment-data.ts';
import { tagSpec } from './tags.ts';

export const PROCESS_READINGS_PATH = '/gw/v1/process-readings';
export const SETPOINT_DOWNLOADS_PATH = '/gw/v1/setpoint-downloads';
export const setpointAckPath = (id: string): string => `${SETPOINT_DOWNLOADS_PATH}/${encodeURIComponent(id)}/ack`;

/** GOOD: read from the device now; UNCERTAIN: the device flags the value; BAD: the device reports it invalid; STALE: the device stopped updating. */
export const ProcessQuality = z.enum(['GOOD', 'UNCERTAIN', 'BAD', 'STALE']);
export type ProcessQuality = z.infer<typeof ProcessQuality>;

/** ACTUAL: a measured value; SETPOINT_READBACK: the setpoint as the device reports it holds it; ALARM / ALARM_CLEARED: an alarm on the tag raised or cleared, with the tag's value then. */
export const ProcessReadingKind = z.enum(['ACTUAL', 'SETPOINT_READBACK', 'ALARM', 'ALARM_CLEARED']);
export type ProcessReadingKind = z.infer<typeof ProcessReadingKind>;

export const ProcessDecimal = z.string().regex(DECIMAL_TEXT, 'a decimal travels as plain decimal text');
export const ProcessSequence = z.string().regex(/^[1-9][0-9]{0,18}$/, 'a sequence number from 1, as text');
export const ProcessEpochMicros = z.string().regex(/^(0|[1-9][0-9]{0,17})$/, 'UTC epoch microseconds as text');
export const DeviceSerial = z.string().regex(/^[\x21\x23-\x7E]{1,32}$/, 'a device serial number (printable, no quote)');
export const ProcessUnit = z.string().min(1).max(16);

/**
 * Phase 6 slice 6b (builder A; DI-32, DI-20): a reading taken over OPC UA keeps the device's original record with it:
 * the raw value text as the server sent it, the OPC UA status code, the source timestamp the server stamped, and the
 * enrolled endpoint (an INSTRUMENT of the device registry) whose session it came through. The value shown (`value`)
 * must state the raw value exactly (never a rounding; tablets 1210 checks it again). Absent for the JSON-lines stand-in.
 */
export const ProcessReadingNative = z.strictObject({
  raw: z.string().regex(/^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]{1,3})?$/, 'a number as the source wrote it').max(40),
  status: z.string().regex(/^0x[0-9A-F]{8}$/, 'an OPC UA status code such as 0x00000000'),
  deviceTime: z.string().regex(/^(0|[1-9][0-9]{0,17})$/, 'the source timestamp, UTC epoch microseconds as text'),
  endpointCode: z.string().regex(/^[A-Za-z0-9][A-Za-z0-9._-]{1,63}$/, 'the endpoint\'s device code'),
});
export type ProcessReadingNative = z.infer<typeof ProcessReadingNative>;

export const ProcessReading = z.strictObject({
  deviceSerial: DeviceSerial,
  tag: z.string().min(1).max(64),
  value: ProcessDecimal,
  unit: ProcessUnit,
  quality: ProcessQuality,
  sourceTime: ProcessEpochMicros,
  sequence: ProcessSequence,
  kind: ProcessReadingKind,
  native: ProcessReadingNative.optional(),
});
export type ProcessReading = z.infer<typeof ProcessReading>;

/** The most readings one request carries. */
export const PROCESS_BATCH_MAX = 200;

export const ProcessReadingsRequest = z.strictObject({
  sessionId: z.uuid(),
  readings: z.array(ProcessReading).min(1).max(PROCESS_BATCH_MAX),
});
export type ProcessReadingsRequest = z.infer<typeof ProcessReadingsRequest>;

/**
 * The server's answer to a batch: any 2xx answer means it holds every reading of the batch (a batch is taken whole or
 * refused whole, DI-31: never a partial transfer). Its members are the server's; the gateway reads none of them.
 */
export const ProcessReadingsResponse = z.looseObject({});

/** One setpoint the server asks the gateway to download to a device (members the gateway does not use are ignored). */
export const SetpointDownload = z.object({
  id: z.string().min(1).max(64),
  deviceSerial: DeviceSerial,
  tag: z.string().min(1).max(64),
  value: ProcessDecimal,
  unit: ProcessUnit,
});
export type SetpointDownload = z.infer<typeof SetpointDownload>;

export const SetpointDownloadsResponse = z.object({ downloads: z.array(SetpointDownload) });
export type SetpointDownloadsResponse = z.infer<typeof SetpointDownloadsResponse>;

/**
 * APPLIED: written and read back equal to the download; MISMATCH: written but the device reads back another value
 * (the read-back says which); FAILED: not written (device offline, refused the value, or the download names a device
 * or tag this gateway does not have), `message` says why.
 */
export const SetpointOutcome = z.enum(['APPLIED', 'MISMATCH', 'FAILED']);
export type SetpointOutcome = z.infer<typeof SetpointOutcome>;

export const SetpointAckRequest = z.strictObject({
  sessionId: z.uuid(),
  outcome: SetpointOutcome,
  /** The SETPOINT_READBACK reading sent for this download (also in process-readings), or null when nothing was read back. */
  readback: z
    .strictObject({ value: ProcessDecimal, unit: ProcessUnit, sourceTime: ProcessEpochMicros, sequence: ProcessSequence })
    .nullable(),
  message: z.string().min(1).max(500).nullable(),
});
export type SetpointAckRequest = z.infer<typeof SetpointAckRequest>;

/**
 * The rules of one reading a schema cannot say: a known tag, in its unit, with at most its fraction digits, a counter
 * never negative, a read-back only of a setpoint tag. Pure; empty when sound.
 */
export function processReadingProblems(r: Pick<ProcessReading, 'tag' | 'value' | 'unit' | 'kind'>): { field: 'tag' | 'unit' | 'value' | 'kind'; message: string }[] {
  const spec = tagSpec(r.tag);
  if (!spec) return [{ field: 'tag', message: `${r.tag} is not a process tag` }];
  const out: { field: 'tag' | 'unit' | 'value' | 'kind'; message: string }[] = [];
  if (r.unit !== spec.unit) out.push({ field: 'unit', message: `${r.tag} is in ${spec.unit}, not ${r.unit}` });
  if (!DECIMAL_TEXT.test(r.value)) out.push({ field: 'value', message: `${r.value} is not plain decimal text` });
  else if (scaleOf(r.value) > spec.scale) out.push({ field: 'value', message: `${r.tag} carries at most ${spec.scale} decimals` });
  if (spec.counter && r.value.startsWith('-')) out.push({ field: 'value', message: `${r.tag} is a count and never negative` });
  if (r.kind === 'SETPOINT_READBACK' && !spec.setpoint) out.push({ field: 'kind', message: `${r.tag} takes no setpoint` });
  return out;
}

export interface ProcessWireProblem {
  /** Where in the body: e.g. "readings.3.unit". */
  path: string;
  message: string;
}

/**
 * Validates a process-readings body: null when sound, otherwise every problem found. Pure (no clock, no I/O).
 * The sequence rule is per batch; continuity with what the server already holds is the server's check.
 */
export function processReadingsProblems(candidate: unknown): ProcessWireProblem[] | null {
  const parsed = ProcessReadingsRequest.safeParse(candidate);
  if (!parsed.success) {
    return parsed.error.issues.map((i) => ({ path: i.path.map(String).join('.'), message: i.message }));
  }
  const problems: ProcessWireProblem[] = [];
  const lastSeq = new Map<string, bigint>();
  parsed.data.readings.forEach((r, i) => {
    for (const p of processReadingProblems(r)) problems.push({ path: `readings.${i}.${p.field}`, message: p.message });
    if (r.native) {
      // DI-32: the value shown is the raw value the device sent, exactly (never a rounding of it).
      const problem = shownValueProblem(r.native.raw, r.value);
      if (problem) problems.push({ path: `readings.${i}.native.raw`, message: problem });
    }
    const seq = BigInt(r.sequence);
    const prev = lastSeq.get(r.deviceSerial);
    if (prev !== undefined && seq <= prev) {
      problems.push({ path: `readings.${i}.sequence`, message: `sequence ${r.sequence} of ${r.deviceSerial} does not follow ${prev.toString()} in this batch` });
    }
    lastSeq.set(r.deviceSerial, prev !== undefined && prev > seq ? prev : seq);
  });
  return problems.length > 0 ? problems : null;
}

packages/integration-sdk/src/serialisati.source:
/**
 * The serialisation L3 contract (Phase 3 slice 4a, K-21, PR-42; the 4a interface of slice-4-plan.md). The tablets
 * server is the client of the site's L3 system (a stub in apps/simulators until the Phase 6 adapter); unit serials and
 * aggregation stay in the L3/L4 system, the record keeps the pool id, the counts, the reconciliation and the report
 * hash.
 *
 *   POST /l3/v1/pools                    PoolRequest -> PoolResponse: a pool of serials for one packaging order
 *   POST /l3/v1/pools/:poolId/events     SerialEventsRequest: serial state events (a batch is taken whole or refused whole)
 *   GET  /l3/v1/pools/:poolId/report     PoolReport: counts per state, unexplained serials and the report hash
 *
 * Quantities and counts are whole decimal text; times are UTC epoch microseconds as text. Every serial must end in a
 * state: COMMISSIONED (on a saleable pack), DECOMMISSIONED, DESTROYED, SAMPLE or UNUSED_RETURNED; a serial issued
 * with no state is unexplained. The report hash is the SHA-256 (lower-case hex) of the canonical report text
 * (canonicalReportText): the same pool in the same states always gives the same hash.
 */
import { createHash } from 'node:crypto';
import { z } from 'zod';
import { Gtin } from '../printer/wire.ts';
import { ProcessEpochMicros } from '../process/wire.ts';
import { MARKETS } from './market.ts';

export const L3_POOLS_PATH = '/l3/v1/pools';
export const l3PoolEventsPath = (poolId: string): string => `${L3_POOLS_PATH}/${encodeURIComponent(poolId)}/events`;
export const l3PoolReportPath = (poolId: string): string => `${L3_POOLS_PATH}/${encodeURIComponent(poolId)}/report`;

/** The most serials one pool holds, and the most events one request carries. */
export const POOL_MAX = 100_000n;
export const SERIAL_EVENTS_MAX = 1000;

const WholeText = z.string().regex(/^(0|[1-9][0-9]{0,17})$/, 'a whole number as decimal text');
export const PoolId = z.string().regex(/^[\x21-\x7E]{1,64}$/);
export const Serial = z.string().regex(/^[A-Za-z0-9/.-]{1,20}$/, 'a serial (GS1 AI 21 subset, at most 20)');

export const PoolRequest = z.strictObject({
  packagingOrder: z.string().regex(/^[\x20-\x7E]{1,64}$/),
  market: z.enum(MARKETS),
  gtin: Gtin,
  quantity: WholeText.refine((q) => q !== '0' && BigInt(q) <= POOL_MAX, `1 to ${POOL_MAX.toString()} serials`),
});
export type PoolRequest = z.infer<typeof PoolRequest>;

export const PoolResponse = z.strictObject({ poolId: PoolId, serials: z.array(Serial).min(1), issuedAt: ProcessEpochMicros });
export type PoolResponse = z.infer<typeof PoolResponse>;

export const SERIAL_STATES = ['COMMISSIONED', 'DECOMMISSIONED', 'DESTROYED', 'SAMPLE', 'UNUSED_RETURNED'] as const;
export const SerialState = z.enum(SERIAL_STATES);
export type SerialState = z.infer<typeof SerialState>;

export const SerialEvent = z.strictObject({ serial: Serial, state: SerialState, at: ProcessEpochMicros });
export type SerialEvent = z.infer<typeof SerialEvent>;
export const SerialEventsRequest = z.strictObject({ events: z.array(SerialEvent).min(1).max(SERIAL_EVENTS_MAX) });
export type SerialEventsRequest = z.infer<typeof SerialEventsRequest>;
/** The stub answers {accepted: "<n>"}; a client reads nothing else from a 2xx. */
export const SerialEventsResponse = z.looseObject({ accepted: WholeText });

/**
 * The state changes a serial may take (from no state = issued): issued -> COMMISSIONED, UNUSED_RETURNED or DESTROYED
 * (a coded set-up unit destroyed before commissioning); COMMISSIONED -> DECOMMISSIONED, DESTROYED or SAMPLE;
 * DECOMMISSIONED -> DESTROYED. DESTROYED, SAMPLE and UNUSED_RETURNED end it. An event repeating the state the serial
 * holds is a repeat, taken as a no-op (a client may resend a batch).
 */
export const SERIAL_TRANSITIONS: Record<SerialState | 'ISSUED', readonly SerialState[]> = {
  ISSUED: ['COMMISSIONED', 'UNUSED_RETURNED', 'DESTROYED'],
  COMMISSIONED: ['DECOMMISSIONED', 'DESTROYED', 'SAMPLE'],
  DECOMMISSIONED: ['DESTROYED'],
  DESTROYED: [],
  SAMPLE: [],
  UNUSED_RETURNED: [],
};

export function serialTransitionAllowed(from: SerialState | null, to: SerialState): boolean {
  return SERIAL_TRANSITIONS[from ?? 'ISSUED'].includes(to);
}

export const PoolCounts = z.strictObject({
  issued: WholeText,
  COMMISSIONED: WholeText,
  DECOMMISSIONED: WholeText,
  DESTROYED: WholeText,
  SAMPLE: WholeText,
  UNUSED_RETURNED: WholeText,
});
export type PoolCounts = z.infer<typeof PoolCounts>;

export const PoolReport = z.strictObject({
  poolId: PoolId,
  counts: PoolCounts,
  /** Serials issued with no state, as whole decimal text. */
  unexplained: WholeText,
  reportHash: z.string().regex(/^[0-9a-f]{64}$/),
});
export type PoolReport = z.infer<typeof PoolReport>;

/** The L3 error body (4xx/5xx). */
export const L3Error = z.strictObject({ error: z.strictObject({ code: z.string().regex(/^[A-Z_]{2,40}$/), message: z.string().max(500) }) });

export interface PoolSnapshot {
  poolId: string;
  packagingOrder: string;
  market: string;
  gtin: string;
  /** Every serial issued with its state now (null: no state). */
  serials: readonly { serial: string; state: SerialState | null }[];
}

export const L3_REPORT_FORMAT = 'ebmr.l3-report.v1';

function compare(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/**
 * The canonical text of a pool report: LF-ended lines, the format name, the pool's identity, the counts in the order
 * of PoolCounts, the unexplained count, then one line per serial in code-unit order of the serial ("<serial> <state>",
 * NONE for no state). Event times are not part of it: the hash names the outcome, not the history.
 */
export function canonicalReportText(pool: PoolSnapshot): string {
  const counts = poolCounts(pool);
  const lines = [
    L3_REPORT_FORMAT,
    `poolId=${pool.poolId}`,
    `packagingOrder=${pool.packagingOrder}`,
    `market=${pool.market}`,
    `gtin=${pool.gtin}`,
    `issued=${counts.issued}`,
    ...SERIAL_STATES.map((s) => `${s}=${counts[s]}`),
    `unexplained=${unexplainedOf(pool).toString()}`,
    ...[...pool.serials].sort((a, b) => compare(a.serial, b.serial)).map((s) => `${s.serial} ${s.state ?? 'NONE'}`),
  ];
  return `${lines.join('\n')}\n`;
}

export function reportHashOf(canonicalText: string): string {
  return createHash('sha256').update(canonicalText, 'utf8').digest('hex');
}

export function poolCounts(pool: PoolSnapshot): PoolCounts {
  const n = (s: SerialState) => BigInt(pool.serials.filter((x) => x.state === s).length).toString();
  return { issued: BigInt(pool.serials.length).toString(), COMMISSIONED: n('COMMISSIONED'), DECOMMISSIONED: n('DECOMMISSIONED'), DESTROYED: n('DESTROYED'), SAMPLE: n('SAMPLE'), UNUSED_RETURNED: n('UNUSED_RETURNED') };
}

function unexplainedOf(pool: PoolSnapshot): bigint {
  return BigInt(pool.serials.filter((s) => s.state === null).length);
}

/** The report of a pool now: counts, unexplained and the hash of its canonical text. Pure. */
export function poolReport(pool: PoolSnapshot): PoolReport {
  return { poolId: pool.poolId, counts: poolCounts(pool), unexplained: unexplainedOf(pool).toString(), reportHash: reportHashOf(canonicalReportText(pool)) };
}

/** Whether a report shows every serial in a state (zero unexplained) and its counts add up to the serials issued. */
export function reportReconciles(report: PoolReport): boolean {
  const sum = SERIAL_STATES.reduce((acc, s) => acc + BigInt(report.counts[s]), 0n);
  return report.unexplained === '0' && sum === BigInt(report.counts.issued);
}

// ---------------------------------------------------------------------------------------------------------------
// Phase 6 slice 6c (PR-42, D-P6c-1): the serial query and the rejection of a pool, additive.
//
//   GET  /l3/v1/serials/:serial          SerialQueryAnswer: the pool, GTIN, packaging order and state the L3 system holds
//                                        for one serial (lot and expiry when the L3 profile carries them)
//   POST /l3/v1/pools/:poolId/reject     PoolRejection -> DecommissionTask: the L3 system opens a decommissioning task
//                                        for the serials commissioned in the pool (the same task again for a repeat)
// The eBMR answers a serial query with the lot and expiry of its own record (the pool's packaging order), never the
// L3's: an L3 lot or expiry that differs from the record is shown as a problem.
// ---------------------------------------------------------------------------------------------------------------

export const l3SerialPath = (serial: string): string => `/l3/v1/serials/${encodeURIComponent(serial)}`;
export const l3PoolRejectPath = (poolId: string): string => `${L3_POOLS_PATH}/${encodeURIComponent(poolId)}/reject`;

export const SerialQueryAnswer = z.strictObject({
  serial: Serial,
  poolId: PoolId,
  gtin: Gtin,
  packagingOrder: z.string().regex(/^[\x20-\x7E]{1,64}$/),
  /** null: issued, no state yet. */
  state: SerialState.nullable(),
  /** The lot (batch number) and expiry (YYYY-MM) the L3 profile carries, when it does. */
  lot: z.string().regex(/^[\x20-\x7E]{1,64}$/).optional(),
  expiry: z.string().regex(/^\d{4}-(0[1-9]|1[0-2])$/).optional(),
});
export type SerialQueryAnswer = z.infer<typeof SerialQueryAnswer>;

export const PoolRejection = z.strictObject({ reason: z.string().regex(/^[\x20-\x7E]{1,500}$/) });
export type PoolRejection = z.infer<typeof PoolRejection>;

export const DecommissionTask = z.strictObject({
  taskId: z.string().regex(/^[\x21-\x7E]{1,64}$/),
  poolId: PoolId,
  packagingOrder: z.string().regex(/^[\x20-\x7E]{1,64}$/),
  reason: z.string().max(500),
  createdAt: ProcessEpochMicros,
  state: z.enum(['OPEN', 'DONE']),
  serials: z.array(Serial),
});
export type DecommissionTask = z.infer<typeof DecommissionTask>;

